&lt;li style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;9pm-5:30a Thursday-Monday&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;11:30pm-8:00a Sunday-Thursday&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
